"""Municipal density quartiles of recovered national relative E2SFCA; fixed 30 min only."""
from pathlib import Path
import pandas as pd,numpy as np,json,datetime
R=Path.cwd()/'research';b=R/'codex';source=b/'R322_national_fca_independent';summary=json.loads((source/'summary.json').read_text(encoding='utf-8'));assert summary['state']=='completed_independent_R200_reproduction' and summary['scope_prefectures']==47
p=pd.read_parquet(b/'R021_inputs/mesh500.parquet',columns=['MESH_ID','SHICODE','PTN_2020']);idx=pd.read_parquet(source/'national_mesh_index.parquet',columns=['MESH_ID','relative_to_national_mean']);p['MESH_ID']=p.MESH_ID.astype(str);idx['MESH_ID']=idx.MESH_ID.astype(str);x=p.merge(idx,on='MESH_ID',how='left',validate='many_to_one');assert not x.relative_to_national_mean.isna().any();x['municipality']=x.SHICODE.astype(str).str.extract(r'^(\d{5})');assert not x.municipality.isna().any();x['weighted_access']=x.PTN_2020*x.relative_to_national_mean
m=x.groupby('municipality').agg(population=('PTN_2020','sum'),populated_meshes=('MESH_ID','nunique'),weighted_access=('weighted_access','sum'));assert len(m)==1884 and (m.population>0).all();m['density']=m.population/(m.populated_meshes*.25);m['relative_access']=m.weighted_access/m.population;m['density_quartile']=pd.qcut(m.density,4,labels=['Q1','Q2','Q3','Q4']);assert m.groupby('density_quartile',observed=True).size().tolist()==[471]*4
rows=[]
for group,d in m.groupby('density_quartile',observed=True):
 rows.append({'density_quartile':str(group),'municipality_count':len(d),'population':float(d.population.sum()),'density_min':float(d.density.min()),'density_max':float(d.density.max()),'population_weighted_relative_e2sfca':float(d.weighted_access.sum()/d.population.sum()),'municipality_median_relative_e2sfca':float(d.relative_access.median()),'municipality_q1_relative_e2sfca':float(d.relative_access.quantile(.25)),'municipality_q3_relative_e2sfca':float(d.relative_access.quantile(.75))})
out=b/'R322_municipality_fca';assert not out.exists();out.mkdir();m.reset_index().to_parquet(out/'municipality_index.parquet',index=False);pd.DataFrame(rows).to_csv(out/'density_quartiles.csv',index=False,encoding='utf-8-sig');result={'state':'completed_municipal_density_quartiles','scope_prefectures':47,'municipal_units':len(m),'population':float(m.population.sum()),'national_weighted_relative':float(m.weighted_access.sum()/m.population.sum()),'rows':rows,'limits':'SHICODE first code; wards separately; area approximated by populated grid cells; old spatial support inherited; unobserved clinical capacity and need','created':datetime.datetime.now().astimezone().isoformat()};(out/'summary.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps(result,ensure_ascii=False),flush=True)
